namespace Notifications;

/// <summary>Computes the backoff delay before the next delivery attempt.</summary>
public sealed class RetryPolicy
{
    private const int MaximumAttempt = 10;
    private const int MaximumDelay = 3600;
    private const int BusyServerThreshold = 600;
    private const int LateAttemptThreshold = 7;
    private const int LateAttemptPenalty = 100;

    public int NextDelay(int attempt, Channel channel, bool serverBusy)
    {
        if (attempt <= 0)
            return 0;
        if (attempt > MaximumAttempt)
            return MaximumDelay;

        int delay = GetBaseDelay(channel) * attempt;
        delay = ApplyServerBusyBackoff(delay, serverBusy);
        return ApplyDelayLimitsAndPenalty(delay, attempt);
    }

    private static int GetBaseDelay(Channel channel)
    {
        switch (channel)
        {
            case Channel.Email:
                return 30;
            case Channel.Sms:
                return 10;
            case Channel.Push:
                return 5;
            default:
                return 15;
        }
    }

    private static int ApplyServerBusyBackoff(int delay, bool serverBusy)
    {
        return serverBusy && delay < BusyServerThreshold ? delay * 2 : delay;
    }

    private static int ApplyDelayLimitsAndPenalty(int delay, int attempt)
    {
        if (delay > MaximumDelay)
            return MaximumDelay;
        if (delay < 1)
            return 1;
        if (attempt > LateAttemptThreshold)
            return delay + LateAttemptPenalty;
        return delay;
    }
}
